 const [tab,setTab]=useState('Dashboard'); const [teacherName,setTeacherName]=useState(''); const [schoolName,setSchoolName]=useState(''); const [className,setClassName]=useState(''); const [selectedClassId,setSelectedClassId]=useState(''); const [lessonDate,setLessonDate]=useState(()=>new Date().toISOString().slice(0,10)); const [lessonTime,setLessonTime]=useState(''); const [homeworkStudentFields]=useState(true); const [homeworkDailyNote,setHomeworkDailyNote]=useState(false); const [homeworkDailyNotePrompt,setHomeworkDailyNotePrompt]=useState('Write 1–2 sentences: What felt easiest or hardest today?'); const [homeworkSections,setHomeworkSections]=useState({warmup:true,practice:true,challenge:false,reflection:false}); const [classes,setClasses]=useState<{id:string,name:string,grade:string,students:string,time:string,classCode?:string,subject?:string}[]>([]); const [classInviteStatus,setClassInviteStatus]=useState(''); const [showCreateClass,setShowCreateClass]=useState(false); const [newClassName,setNewClassName]=useState('Grade 7 Math'); const [newClassGrade,setNewClassGrade]=useState('7'); const [newClassSubject,setNewClassSubject]=useState('Math'); const [newClassPeriod,setNewClassPeriod]=useState(''); const [classLoading,setClassLoading]=useState(false); const [onboarding,setOnboarding]=useState(false); const [outputMode,setOutputMode]=useState<'classroom'|'homework'>('classroom'); const [mastery,setMastery]=useState<[string,number][]>(initialMastery); const [grade,setGrade]=useState('7'); const [students,setStudents]=useState('24'); const [minutes,setMinutes]=useState('50'); const [topic,setTopic]=useState('Two-Step Equations');
