 const [files,setFiles]=useState<File[]>([]); const [evidenceFile,setEvidenceFile]=useState<File|null>(null); const [evidenceType,setEvidenceType]=useState('Quiz'); const [evidenceLoading,setEvidenceLoading]=useState(false); const [evidenceError,setEvidenceError]=useState(''); const [evidenceResult,setEvidenceResult]=useState<any>(null); const [fileUse,setFileUse]=useState<Record<string,string>>({}); const [notes,setNotes]=useState(''); const [noteUse,setNoteUse]=useState('teaching-preferences'); const [material,setMaterial]=useState<{title:string,content:string,demo?:boolean}|null>(null); const [loadingMaterial,setLoadingMaterial]=useState('');
 const composing=useRef(false); const [pptLoading,setPptLoading]=useState(false); const [pptError,setPptError]=useState(''); const [generatedDeck,setGeneratedDeck]=useState<any>(null); const [previewSlide,setPreviewSlide]=useState(0); const [generatedConfigKey,setGeneratedConfigKey]=useState('');
