 const [studentRoster,setStudentRoster]=useState<{key:string;studentId?:string;name:string;email?:string;status:string}[]>([]); const [rosterLoading,setRosterLoading]=useState(false); const [showAddStudent,setShowAddStudent]=useState(false); const [addStudentName,setAddStudentName]=useState(''); const [addStudentEmail,setAddStudentEmail]=useState(''); const [addStudentStatus,setAddStudentStatus]=useState(''); const [locationLoading,setLocationLoading]=useState(false); const [locationMessage,setLocationMessage]=useState(''); const [attendanceDate,setAttendanceDate]=useState(()=>new Date().toISOString().slice(0,10)); const [studentAttendance,setStudentAttendance]=useState<Record<string,string>>({}); const [attendanceSaved,setAttendanceSaved]=useState(false); const [attendanceSubmitting,setAttendanceSubmitting]=useState(false); const [attendanceMessage,setAttendanceMessage]=useState(''); const [attendanceSubmittedAt,setAttendanceSubmittedAt]=useState(''); const [attendanceDirty,setAttendanceDirty]=useState(false); const [attendanceHistory,setAttendanceHistory]=useState<any[]>([]); const [workRecords,setWorkRecords]=useState<any[]>([]); const [workNow,setWorkNow]=useState<any>(null); const [leaveRequests,setLeaveRequests]=useState<any[]>([]); const [leaveStart,setLeaveStart]=useState(()=>new Date().toISOString().slice(0,10)); const [leaveEnd,setLeaveEnd]=useState(()=>new Date().toISOString().slice(0,10)); const [leaveType,setLeaveType]=useState('Full day'); const [leaveReason,setLeaveReason]=useState('Personal'); const [leaveNote,setLeaveNote]=useState(''); const [leaveSaved,setLeaveSaved]=useState(false);
 useEffect(()=>{try{const saved=localStorage.getItem('edu-profile-v1');if(!saved)setOnboarding(false)}catch{setOnboarding(false)}},[]);
