 async function loadLeaveRequests(){try{const r=await fetch('/api/school-ops',{headers:{Authorization:`Bearer ${getAccessToken()}`}});const d=await r.json();if(d.connected&&Array.isArray(d.timeOff))setLeaveRequests(d.timeOff)}catch{}}
