 useEffect(()=>{if(typeof window!=='undefined')localStorage.setItem('edu-homework-prefs-v1',JSON.stringify({sections:homeworkSections,dailyNote:homeworkDailyNote,dailyNotePrompt:homeworkDailyNotePrompt}))},[homeworkSections,homeworkDailyNote,homeworkDailyNotePrompt]);
